require dirname(__DIR__).'/includes/bootstrap.php'; if(!installed())redirect('setup.php');verify_csrf();$email=strtolower(trim((string)($_POST['email']??'')));$password=(string)($_POST['password']??'');$_SESSION['_old']['email']=$email;$ip=$_SERVER['REMOTE_ADDR']??'unknown';
try{$q=db()->prepare('SELECT COUNT(*) FROM login_attempts WHERE email=? AND ip_address=? AND successful=0 AND attempted_at > (UTC_TIMESTAMP()-INTERVAL 15 MINUTE)');$q->execute([$email,$ip]);if((int)$q->fetchColumn()>=8){flash('error','Too many failed attempts. Try again in 15 minutes.');redirect('login.php');}$ok=filter_var($email,FILTER_VALIDATE_EMAIL)&&login_user($email,$password);db()->prepare('INSERT INTO login_attempts(email,ip_address,successful) VALUES(?,?,?)')->execute([$email,$ip,$ok?1:0]);if(!$ok){flash('error','Invalid email or password.');redirect('login.php');}clear_old();redirect('dashboard.php');}catch(Throwable $e){flash('error','Unable to sign in. Check that MySQL is running.');redirect('login.php');}
